#include <bits/stdc++.h>
using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n,m;
    cin>>n>>m;
    int a[10];
    for(int i=0;i<10;i++) cin>>a[i];

    vector<vector<int>> adj(n+1), radj(n+1);
    for(int i=0;i<m;i++){
        int u,v; cin>>u>>v;
        adj[u].push_back(v);
        radj[v].push_back(u);
    }

    auto now=chrono::steady_clock::now;
    auto start_time=now();
    auto elapsed_ms=[&](){return chrono::duration_cast<chrono::milliseconds>(now()-start_time).count();};

    // Check DAG
    {
        vector<int> indeg(n+1,0);
        for(int u=1;u<=n;u++) for(int v:adj[u]) indeg[v]++;
        queue<int> q;
        for(int u=1;u<=n;u++) if(indeg[u]==0) q.push(u);
        vector<int> topo;
        topo.reserve(n);
        while(!q.empty()){int u=q.front();q.pop();topo.push_back(u);for(int v:adj[u])if(--indeg[v]==0)q.push(v);}
        if((int)topo.size()==n){
            vector<int> dp(n+1,1),nxt(n+1,-1);
            for(int i=n-1;i>=0;i--){
                int u=topo[i]; dp[u]=1; nxt[u]=-1;
                for(int v:adj[u]) if(dp[v]+1>dp[u]){dp[u]=dp[v]+1;nxt[u]=v;}
            }
            int bs=topo[0]; for(int u:topo) if(dp[u]>dp[bs]) bs=u;
            vector<int> path; for(int u=bs;u!=-1;u=nxt[u]) path.push_back(u);
            cout<<path.size()<<"\n";
            for(int i=0;i<(int)path.size();i++){if(i)cout<<' ';cout<<path[i];}
            cout<<"\n";
            return 0;
        }
    }

    mt19937 rng(42);
    vector<int> best_path;

    // DFS with time limit for small n
    if(n<=1000 && m<=5000){
        vector<bool> vis(n+1,false);
        vector<int> cur_path;
        function<void(int)> dfs=[&](int u){
            if(elapsed_ms()>3500) return;
            cur_path.push_back(u); vis[u]=true;
            if((int)cur_path.size()>(int)best_path.size()) best_path=cur_path;
            if((int)best_path.size()==n){vis[u]=false;cur_path.pop_back();return;}
            // Sort neighbors by out-degree (Warnsdorff)
            vector<pair<int,int>> nb;
            for(int v:adj[u]) if(!vis[v]){int c=0;for(int w:adj[v])if(!vis[w])c++;nb.push_back({c,v});}
            sort(nb.begin(),nb.end());
            for(auto&[c,v]:nb){if(elapsed_ms()>3500)break;dfs(v);if((int)best_path.size()==n)break;}
            vis[u]=false; cur_path.pop_back();
        };
        vector<int> order(n); iota(order.begin(),order.end(),1);
        shuffle(order.begin(),order.end(),rng);
        for(int s:order){if(elapsed_ms()>3500||(int)best_path.size()==n)break;dfs(s);}
    }

    // Greedy restarts
    while(elapsed_ms()<4500&&(int)best_path.size()<n){
        int sv=rng()%n+1;
        vector<int> path={sv};
        vector<int> pos(n+1,-1); pos[sv]=0;
        auto ext_back=[&]()->bool{int c=path.back();int b=-1,bs=INT_MAX;for(int v:adj[c])if(pos[v]==-1){int s=0;for(int w:adj[v])if(pos[w]==-1)s++;if(s<bs||(s==bs&&(rng()&1))){bs=s;b=v;}}if(b==-1)return false;pos[b]=(int)path.size();path.push_back(b);return true;};
        auto ext_front=[&]()->bool{int c=path[0];int b=-1,bs=INT_MAX;for(int v:radj[c])if(pos[v]==-1){int s=0;for(int w:radj[v])if(pos[w]==-1)s++;if(s<bs||(s==bs&&(rng()&1))){bs=s;b=v;}}if(b==-1)return false;path.insert(path.begin(),b);for(int i=0;i<(int)path.size();i++)pos[path[i]]=i;return true;};
        while(ext_back());while(ext_front());while(ext_back());
        if((int)path.size()>(int)best_path.size()) best_path=path;
    }

    cout<<best_path.size()<<"\n";
    for(int i=0;i<(int)best_path.size();i++){if(i)cout<<' ';cout<<best_path[i];}
    cout<<"\n";
}
